message.content:
{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile against a plain light background, combining the body of a gray wolf with the hard exoskeleton and chelipeds of a large crustacean. The head, neck, chest, belly, hind legs and tail are covered in dense, shaggy gray, white and tan wolf fur, while the back is covered by a large, glossy, dark gray-black segmented carapace, the neck is encircled by overlapping armored plates that also cap the top of the head, and the two front limbs are thick, jointed, spiny, dark-mottled crustacean limbs ending in heavy pincers that contact the ground like legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf head in profile with an elongated pointed snout, black nose, closed mouth, yellow-brown eye, and gray-white-tan fur with a lighter muzzle and throat",
      "where": "at the front end of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular wolf ears with gray outer fur and lighter inner fur, with dark armored plates fitted around and between them",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four legs total; the two hind legs are muscular, fully furred wolf legs, and the two front legs are thick, heavily segmented, spiny, dark glossy crustacean chelipeds with distinct joints",
      "where": "hind legs under the rear body and hips, front crustacean legs under the chest and shoulders, all supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with rounded toe pads and short dark claws; front feet are large, dark, mottled, bulbous crab/lobster pincers with a fixed and movable claw finger forming a pincer tip",
      "where": "at the ends of the legs, hind paws on the ground at the rear, large pincers on the ground at the front"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, bushy wolf tail covered in long gray fur, slightly darker at the tip, hanging down and curving slightly",
      "where": "extending from the rear of the body behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large, domed, glossy, dark slate-gray to black segmented carapace with visible sutures between plates, a slightly bumpy reflective surface, and a scalloped, spiny rear and side margin",
      "where": "covering the dorsal back from just behind the neck plates to above the hips, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "overlapping, smooth, dark brown-black armored plates with a hard, slightly shiny surface and rounded edges, forming a collar around the neck and a cap over the top of the head between the ears, with smaller plates at the front shoulder joints and around the upper front limbs",
      "where": "encircling the neck, covering the top of the head between and around the ears, and at the junction of the front limbs and body"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "crab"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
